excels.excel:

EXPORT WITH SHEET="产品销售月度趋势表", HEADER=true,
    MAPPING={"a":"月份","b":"销售数量","c":"单价","d":"销售额","e":"环比增长率"},
    FORMAT={"b":"#,##0","c":"#,##0.00","d":"#,##0.00","e":"0.00%"},
    FORMULAS={
        D2:'B2*C2',D3:'B3*C3',D4:'B4*C4',D5:'B5*C5',D6:'B6*C6',
        E3:'(D3-D2)/D2',E4:'(D4-D3)/D3',E5:'(D5-D4)/D4',E6:'(D6-D5)/D5',
        B7:'SUM(B2:B6)',D7:'SUM(D2:D6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}
    }
